B.nb=new A.R(58233,"MaterialIcons",!1)
B.O1=new A.r("candles","Chandelier Candles","dining",5,"The chandelier is the only light fitting in the dining room. Every candle in it is brand new, the wicks still white and waxed. None of them has ever been lit.",B.nb,B.T,null,B.f,B.b,!1,null)
