B.Rt=new A.R(58305,"MaterialIcons",!1)
B.Ob=new A.r("tickets","Packed Suitcase","groom",0,"A suitcase at the bottom of his wardrobe, initialled G.C. Inside: a spare collar and two one-way train tickets to Biscotti Bay for tonight \u2014 \u201cMr. G. Cracker\u201d and \u201cMiss T. Misu\u201d.",B.Rt,B.ay,"gwardrobe",B.f,B.b,!1,null)
